mapper.select:
select from basket_discipline_record where season_id = #{seasonId} and discipline_status = 1 and record_status = 'ACTIVE' and is_delete = 0 and effective_start_time <= #{now} and (effective_end_time is null or effective_end_time >= #{now})
and member_id in #{mid}
and 1 = 0

select d.id, d.record_no as recordNo, d.target_type as targetType, d.season_id as seasonId, coalesce(nullif(trim(s.display_title), ''), s.season_name) as seasonName, ser.series_name as seriesName, et.division_id as divisionId, bd.division_name as divisionName, d.team_id as teamId, t.team_name as teamName, d.event_team_id as eventTeamId, et.team_name_snapshot as eventTeamName, d.player_id as playerId, p.player_no as playerNo, coalesce(nullif(trim(p.game_nickname), ''), nullif(trim(mp.nickname), ''), p.player_no) as playerName, d.member_id as memberId, d.discipline_type as disciplineType, d.penalty_code as penaltyCode, d.title, d.reason_text as reasonText, d.discipline_status as disciplineStatus, d.record_status as recordStatus, d.execution_status as executionStatus, d.execution_match_forfeit_count as executionMatchForfeitCount, d.execution_series_forfeit_count as executionSeriesForfeitCount, d.execution_qualification_removed_count as executionQualificationRemovedCount, d.execution_warning_count as executionWarningCount, d.announcement_id as announcementId, a.announcement_status as announcementStatus, d.match_suspension_remaining as matchSuspensionRemaining, d.point_deduction as pointDeduction, d.effective_start_time as effectiveStartTime, d.effective_end_time as effectiveEndTime, d.decision_time as decisionTime, d.create_time as createTime from basket_discipline_record d left join basket_season s on s.id = d.season_id and s.is_delete = 0 left join basket_series ser on ser.id = s.series_id and ser.is_delete = 0 left join basket_team t on t.id = d.team_id and t.is_delete = 0 left join basket_event_team et on et.id = d.event_team_id and et.is_delete = 0 left join basket_division bd on bd.id = et.division_id and bd.is_delete = 0 left join basket_player_profile p on p.id = d.player_id and p.is_delete = 0 left join basket_member_profile mp on mp.member_id = d.member_id and mp.is_delete = 0 left join basket_announcement a on a.id = d.announcement_id and a.is_delete = 0 where d.is_delete = 0 and d.season_id = #{seasonId} and s.series_id = #{tournamentId} and d.team_id = #{teamId} and d.player_id = #{playerId} and d.member_id = #{memberId} and d.target_type = #{targetType} and d.record_status = #{recordStatus} and d.penalty_code = #{penaltyCode}
and (d.record_no like concat('%', #{keyword}, '%') or d.title like concat('%', #{keyword}, '%'))
order by d.create_time desc, d.id desc

mapper.sql:
where is_delete = 0 and record_status = 'ACTIVE'


        and target_type = 'PLAYER' and player_id = #{subjectId}


        and target_type = 'PERMANENT_TEAM' and team_id = #{subjectId}


        and target_type = 'EVENT_TEAM' and event_team_id = #{subjectId}


        and target_type = 'ACCOUNT' and member_id = #{subjectId}


        and 1 = 0



    and season_id = #{seasonId}
    and season_id is null
